package com.bank.part.service;

import com.bank.part.model.Transaction;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

@Service
public class TransactionService {
    private static final Logger log = LoggerFactory.getLogger(TransactionService.class);
    private final JdbcTemplate jdbc;

    public TransactionService(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    // Insert routes automatically to the correct monthly partition by txn_date.
    public void record(Transaction t) {
        jdbc.update("INSERT INTO transactions (account_id, amount, txn_date) VALUES (?,?,?)",
            t.getAccountId(), t.getAmount(), t.getTxnDate());
        log.info("Recorded {} on {} → partition for {}", t.getAmount(), t.getTxnDate(),
            t.getTxnDate().getMonth());
    }

    // Query filters on the partition key (txn_date) so the planner prunes to ONE partition.
    public List<BigDecimal> amountsInMonth(LocalDate from, LocalDate to) {
        log.info("Querying {} to {} — partition pruning skips other months", from, to);
        return jdbc.queryForList(
            "SELECT amount FROM transactions WHERE txn_date >= ? AND txn_date < ?",
            BigDecimal.class, from, to);
    }

    // Hot read only touches the narrow accounts table (vertical partitioning benefit).
    public BigDecimal balance(String accountId) {
        return jdbc.queryForObject(
            "SELECT balance FROM accounts WHERE account_id = ?", BigDecimal.class, accountId);
    }
}
